// Feature 020 (FR-020.1; CF-1, CF-2, CF-16, CF-25 m4/m5): the rebrand export loader for Vitest.
// Reads ../docs/legacy-identifiers.md (repository root), falling back to the public variant the
// mirror carries; refuses an unknown format, an inline flag group in pattern_js and a literal that
// `new RegExp(pattern_js, js_flags)` misses (the JavaScript half of CF-25 m5). Never edited by hand:
// the files are generated by the suite's census.py --export miDataworks.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

export const REPO_ROOT = path.resolve(import.meta.dirname, '../../..');
export const PHASES = ['P0', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8'] as const;
const INLINE_FLAGS = /\(\?[a-zA-Z]+[:)]/;

export type ExportRecord = Record<string, unknown> & { section: string };
export interface ExportHeader {
  format: number;
  repo: string;
  variant: 'full' | 'public';
  phase: string;
  closed: string | null;
  withheld: string[];
}
export interface Export {
  header: ExportHeader;
  records: ExportRecord[];
  file: string;
}

export function compileJs(record: { pattern_js: string; js_flags: string }, global = false): RegExp {
  return new RegExp(record.pattern_js, record.js_flags + (global ? 'g' : ''));
}

export function parseExport(text: string, file = '<text>'): Export {
  const block = /^```jsonl\n([\s\S]*?)^```$/m.exec(text);
  if (!block) throw new Error(`${file}: no jsonl block`);
  const lines = block[1].split('\n').filter((l) => l.trim());
  const header = JSON.parse(lines[0]) as ExportHeader;
  if (header.format !== 1) throw new Error(`${file}: format ${header.format} is not 1`);
  if (!('closed' in header)) throw new Error(`${file}: header has no closed`);
  const records = lines.slice(1).map((l) => JSON.parse(l) as ExportRecord);
  for (const r of records) {
    if (r.section !== 'entry' && r.section !== 'guard') continue;
    const where = `${file}: ${String(r.id)}`;
    if (r.js_flags !== '' && r.js_flags !== 'i') throw new Error(`${where}: js_flags ${String(r.js_flags)}`);
    if (INLINE_FLAGS.test(String(r.pattern_js))) throw new Error(`${where}: pattern_js carries an inline flag group`);
    const rx = compileJs(r as unknown as { pattern_js: string; js_flags: string });
    for (const literal of (r.literals as string[] | undefined) ?? []) {
      if (!rx.test(literal)) throw new Error(`${where}: literal ${literal} is not matched by pattern_js`);
    }
  }
  return { header, records, file };
}

export function loadExport(root = REPO_ROOT): Export {
  for (const name of ['legacy-identifiers.md', 'legacy-identifiers.public.md']) {
    const file = path.join(root, 'docs', name);
    if (existsSync(file)) return parseExport(readFileSync(file, 'utf-8'), file);
  }
  throw new Error(`neither docs/legacy-identifiers.md nor the public variant exists under ${root}`);
}

/** The entry, or null when the public variant withholds it (the caller skips it BY NAME). */
export function entryOrWithheld(exp: Export, id: string): ExportRecord | 'withheld' | undefined {
  const found = exp.records.find((r) => r.section === 'entry' && r.id === id);
  if (found) return found;
  return exp.header.variant === 'public' && exp.header.withheld.includes(id) ? 'withheld' : undefined;
}

function phaseIndex(p: string): number {
  return PHASES.indexOf(p as (typeof PHASES)[number]);
}

export function activeGuards(exp: Export): ExportRecord[] {
  const phase = phaseIndex(exp.header.phase);
  return exp.records.filter(
    (r) =>
      r.section === 'guard' &&
      (r.from_phase == null || phase >= phaseIndex(String(r.from_phase))) &&
      (r.until_phase == null || phase < phaseIndex(String(r.until_phase))),
  );
}

interface Hit {
  start: number;
  end: number;
  text: string;
}

const escapeRx = (text: string): string => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function unallowed(text: string, exp: Export, deny: string): Hit[] {
  const allow: RegExp[] = [];
  for (const r of exp.records) {
    if (r.section === 'entry' && (r.status === 'frozen' || r.status === 'scheduled')) {
      allow.push(compileJs(r as unknown as { pattern_js: string; js_flags: string }, true));
      for (const lit of (r.literals as string[]) ?? []) allow.push(new RegExp(escapeRx(lit), 'g'));
    } else if ((r.section === 'env' || r.section === 'repo') && r.status === 'transition') {
      allow.push(new RegExp(escapeRx(String(r.old)), 'g'));
    } else if (r.section === 'host' && r.status === 'transition') {
      // An old address in transition, as a whole host name: never as the start of a longer label.
      allow.push(new RegExp(`(?<![A-Za-z0-9_.-])${escapeRx(String(r.old))}(?![A-Za-z0-9_-])`, 'g'));
    }
  }
  const denies: RegExp[] = [new RegExp(deny.replace(/^\(\?i\)/, ''), deny.startsWith('(?i)') ? 'gi' : 'g')];
  for (const g of activeGuards(exp)) {
    const rx = compileJs(g as unknown as { pattern_js: string; js_flags: string }, true);
    (g.effect === 'allow' ? allow : denies).push(rx);
  }
  const spans: [number, number][] = [];
  for (const rx of allow) for (const m of text.matchAll(rx)) if (m[0]) spans.push([m.index ?? 0, (m.index ?? 0) + m[0].length]);
  const found = new Map<string, Hit>();
  for (const rx of denies) {
    for (const m of text.matchAll(rx)) {
      const start = m.index ?? 0;
      const end = start + m[0].length;
      if (!spans.some(([a, b]) => a <= start && end <= b) && !found.has(`${start}:${end}`)) found.set(`${start}:${end}`, { start, end, text: m[0] });
    }
  }
  return [...found.values()].sort((x, y) => x.start - y.start || x.end - y.end);
}

/** The brand guard's allow and deny logic, from the export only (FTID §7.5). */
export function unallowedHits(text: string, exp: Export, deny: string): string[] {
  return unallowed(text, exp, deny).map((h) => h.text);
}

// An identifier token: a name a program reads, optionally a kind with its version suffix.
const IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_.]*(?:\/v?[0-9]+)?$/;
const CODE_SPAN = /`([^`\n]+)`/g;

/** The scope rule (FPRD Q4, PD-7), the twin of the pytest loader's `is_identifier_token`: an
 * identifier-shaped token is reported, not enforced, unless it IS the old name in a display form
 * (any capital), which is read wherever it stands. */
function isIdentifierToken(token: string, hit: string): boolean {
  if (!IDENTIFIER.test(token)) return false;
  return !(token === hit && hit !== hit.toLowerCase());
}

/** The unallowed hits of `text` split by scope. `whole`: the text is one literal. `codeSpans`: a
 * backtick code span holding one token is an identifier too. The two lists together are exactly
 * `unallowedHits`. backend/tests/unit/brand/scope_cases.json holds both loaders to the same answers. */
export function classifiedHits(text: string, exp: Export, deny: string, scope: { whole?: boolean; codeSpans?: boolean } = {}): { read: string[]; identifier: string[] } {
  const whole = scope.whole ?? true;
  const spans: [number, number][] = [];
  if (scope.codeSpans ?? true) for (const m of text.matchAll(CODE_SPAN)) spans.push([(m.index ?? 0) + 1, (m.index ?? 0) + 1 + m[1].length]);
  const read: string[] = [];
  const identifier: string[] = [];
  for (const hit of unallowed(text, exp, deny)) {
    let token: string | undefined = whole && isIdentifierToken(text, hit.text) ? text : undefined;
    if (token === undefined) {
      const span = spans.find(([a, b]) => a <= hit.start && hit.end <= b);
      if (span) token = text.slice(span[0], span[1]);
    }
    (token !== undefined && isIdentifierToken(token, hit.text) ? identifier : read).push(hit.text);
  }
  return { read, identifier };
}

/** True only when `root`'s HEAD is the snapshot sync-to-clean.yml publishes: a parentless commit
 * with the `Source-Commit: <sha>` and `Private-CI: passed` trailers. The twin of
 * backend/tests/support/source_tree.py's `mirror_snapshot`. No git, or no repository: false. */
export function mirrorSnapshot(root = REPO_ROOT): boolean {
  try {
    const run = (args: string[]): string => execFileSync('git', args, { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] }).toString('utf-8');
    if (run(['rev-list', '--parents', '-n', '1', 'HEAD']).trim().split(/\s+/).length !== 1) return false;
    const trailers = run(['log', '-1', '--format=%(trailers:only,unfold)', 'HEAD']);
    return trailers.split('\n').includes('Private-CI: passed') && /^Source-Commit: [0-9a-f]{40}$/m.test(trailers);
  } catch {
    return false;
  }
}

/** The mode the frontend scanner applies (suite decision R23): the policy's mode in the private
 * tree, `report` on the public mirror snapshot, whose export withholds allowances this tree has. */
export function appliedMode(policyMode: string, root = REPO_ROOT): string {
  return policyMode === 'enforce' && mirrorSnapshot(root) ? 'report' : policyMode;
}
